//! Debounced file-system watch over the project tree.

pub mod debounce;

/// Collapses a burst of observed event paths into the paths that settled.
pub fn settled(events: Vec<String>) -> Vec<String> {
    debounce::collapse(events)
}

#[cfg(test)]
mod tests {
    use super::settled;

    #[test]
    fn settled_collapses_a_repeated_path() {
        let out = settled(vec!["a.rs".to_owned(), "a.rs".to_owned()]);
        assert_eq!(out, vec!["a.rs".to_owned()]);
    }
}

//! Collapsing a burst of event paths into the settled set.

use std::collections::BTreeSet;

/// Collapses a burst of event paths into the settled set, in sorted order.
pub fn collapse(events: Vec<String>) -> Vec<String> {
    events.into_iter().collect::<BTreeSet<_>>().into_iter().collect()
}

#[cfg(test)]
mod tests {
    use super::collapse;

    #[test]
    fn collapse_deduplicates_and_orders() {
        let out = collapse(vec!["b".to_owned(), "a".to_owned(), "b".to_owned()]);
        assert_eq!(out, vec!["a".to_owned(), "b".to_owned()]);
    }
}
